355		if _, err := n.BlockAt(0); reason(err) != ReasonUnknownBlock {
356			t.Fatalf("height 0 after confirm got %v, want %s", err, ReasonUnknownBlock)
357		}
358		if _, err := n.BlockAt(2); reason(err) != ReasonUnknownBlock {
359			t.Fatalf("height beyond tip after confirm got %v, want %s", err, ReasonUnknownBlock)
360		}
361		if latest, ok := n.LatestBlock(); !ok || latest.ID != p.BlockID || latest.Height != 1 {
362			t.Fatalf("latest after confirm wrong: %+v ok=%v", latest, ok)
