98	// canonicalTxDoc 按 README 的公开规则手工拼接规范 JSON：
99	// 字段按名字典序、无任何多余空白；signatureB64 为空时省略签名字段。
100	func canonicalTxDoc(v encVector, signatureB64 string) string {
101		doc := fmt.Sprintf(
102			`{"content":%q,"expiry":%d,"fee":%d,"sender":%q,"sequence":%d`,
103			v.contentB64, v.expiry, v.fee, stableSenderB64, v.sequence,
104		)
105		if signatureB64 != "" {
106			doc += fmt.Sprintf(`,"signature":%q`, signatureB64)
107		}
108		return doc + "}"
109	}
110	
111	func mustB64Decode(t *testing.T, s string) []byte {
112		t.Helper()
113		b, err := base64.StdEncoding.DecodeString(s)
114		if err != nil {
115			t.Fatalf("invalid base64 %q: %v", s, err)
116		}
117		return b
118	}
119	
120	// jsonKeyOrder 返回 JSON 对象顶层键的实际出现次序。
121	func jsonKeyOrder(t *testing.T, raw []byte) []string {
122		t.Helper()
123		dec := json.NewDecoder(bytes.NewReader(raw))
124		tok, err := dec.Token()
125		if err != nil || tok != json.Delim('{') {
126			t.Fatalf("not a JSON object: %s", raw)
127		}
128		var order []string
129		for dec.More() {
130			key, err := dec.Token()
131			if err != nil {
132				t.Fatal(err)
133			}
134			order = append(order, key.(string))
135			var skip json.RawMessage
136			if err := dec.Decode(&skip); err != nil {
137				t.Fatal(err)
138			}
139		}
140		return order
141	}
