143	// 待签名字节必须是公开的固定前缀（含末尾换行）加无空白、字段按名字典序
144	// 排列的 JSON；签名本身不进入待签名字节，符合这些字节的标准 Ed25519
145	// 签名必须通过现有验签。
146	func TestSigningBytesExactVectors(t *testing.T) {
147		priv := stablePrivateKey(t)
148		pub := priv.Public().(ed25519.PublicKey)
149	
150		for _, v := range stableVectors() {
151			t.Run(v.name, func(t *testing.T) {
152				tx := &Transaction{
153					Sender:   append([]byte(nil), pub...),
154					Sequence: v.sequence,
155					Content:  append([]byte(nil), v.content...),
156					Fee:      v.fee,
157					Expiry:   v.expiry,
158				}
159				signing := tx.SigningBytes()
160				wantDoc := canonicalTxDoc(v, "")
161				want := []byte(stableSigningPrefix + wantDoc)
162	
163				// 钉住确切字节：次序、换行、填充或十进制表示一旦变化即失配。
164				if !bytes.Equal(signing, want) {
165					t.Fatalf("signing bytes mismatch:\n got %q\nwant %q", signing, want)
166				}
167	
168				// 固定前缀及其唯一的末尾换行：前缀后必须紧接 JSON。
169				if !bytes.HasPrefix(signing, []byte(stableSigningPrefix)) {
170					t.Fatalf("missing fixed prefix %q", stableSigningPrefix)
171				}
172				jsonPart := signing[len(stableSigningPrefix):]
173				if len(jsonPart) == 0 || jsonPart[0] != '{' || jsonPart[len(jsonPart)-1] != '}' {
174					t.Fatalf("prefix must be followed immediately by the JSON object: %q", signing)
175				}
176	
177				// JSON 内不得出现任何空白。
178				if bytes.ContainsAny(jsonPart, " \t\r\n") {
179					t.Fatalf("canonical JSON must contain no whitespace: %q", jsonPart)
180				}
181	
182				// 字段次序：content < expiry < fee < sender < sequence（按名字典序）。
183				if order := jsonKeyOrder(t, jsonPart); strings.Join(order, ",") !=
184					"content,expiry,fee,sender,sequence" {
185					t.Fatalf("unexpected field order: %v", order)
186				}
187	
188				// 序号、费用、到期轮次是无符号整数的十进制表示：不带引号、
189				// 不带小数点/指数，且与 strconv 十进制结果逐字一致。
190				var fields map[string]json.RawMessage
191				if err := json.Unmarshal(jsonPart, &fields); err != nil {
192					t.Fatal(err)
193				}
194				decimals := map[string]uint64{
195					"sequence": v.sequence,
196					"fee":      v.fee,
197					"expiry":   v.expiry,
198				}
199				for name, num := range decimals {
200					raw := string(fields[name])
201					if raw != strconv.FormatUint(num, 10) {
202						t.Fatalf("field %s encoded as %q, want plain decimal %d", name, raw, num)
203					}
204					if raw[0] == '"' || strings.ContainsAny(raw, ".eE+") {
205						t.Fatalf("field %s must be a bare JSON integer, got %q", name, raw)
206					}
207				}
208	
209				// 发送者与内容为标准 Base64（带填充），且内容字节可完整还原。
210				var view struct {
211					Sender  string `json:"sender"`
212					Content string `json:"content"`
213				}
214				if err := json.Unmarshal(jsonPart, &view); err != nil {
215					t.Fatal(err)
216				}
217				if view.Sender != stableSenderB64 {
218					t.Fatalf("sender base64 = %q, want %q", view.Sender, stableSenderB64)
219				}
220				if view.Content != v.contentB64 {
221					t.Fatalf("content base64 = %q, want %q", view.Content, v.contentB64)
222				}
223				if got := mustB64Decode(t, view.Content); !bytes.Equal(got, v.content) {
224					t.Fatalf("content bytes not preserved: got %v, want %v", got, v.content)
225				}
226	
227				// 签名本身不进入待签名字节。
228				if bytes.Contains(signing, []byte("signature")) {
229					t.Fatalf("signing bytes must not contain the signature field: %q", signing)
230				}
231	
232				// 钉住的标准 Ed25519 签名必须通过现有验签与独立验签。
233				sig := mustB64Decode(t, v.signatureB64)
234				tx.Signature = sig
235				if !tx.Verify() {
236					t.Fatal("pinned signature must verify via Transaction.Verify")
237				}
238				if !ed25519.Verify(pub, want, sig) {
239					t.Fatal("pinned signature must verify against the pinned bytes with stdlib")
240				}
241				// 反向钉住向量本身：对公开字节重新签名必须得到同一签名。
242				if got := ed25519.Sign(priv, want); !bytes.Equal(got, sig) {
243					t.Fatalf("signature over public bytes differs from pinned vector")
244				}
245	
246				// 前缀末尾换行或任何字节被改动后，同一签名必须失效——
247				// 这证明钉住的是公开字节约定，而非本地自洽的另一套表示。
248				if ed25519.Verify(pub, append(append([]byte{}, signing...), '\n'), sig) {
249					t.Fatal("appending a byte must invalidate the pinned signature")
250				}
251				moved := append([]byte{}, signing...)
252				moved[len(stableSigningPrefix)-1] = 'X' // 破坏前缀末尾换行
253				if ed25519.Verify(pub, moved, sig) {
254					t.Fatal("changing the prefix newline must invalidate the pinned signature")
255				}
256				if ed25519.Verify(pub, jsonPart, sig) {
257					t.Fatal("dropping the fixed prefix must invalidate the pinned signature")
258				}
259			})
260		}
261	}
