263	// 交易标识必须是含签名字段的规范 JSON 的 SHA-256 十六进制摘要：
264	// 不带签名前缀，签名字段为标准 Base64 且按字段名排在 sequence 之后，
265	// 输出为小写 64 位；重新提供相同字段与签名字节必须得到相同标识。
266	func TestTransactionIDExactVectors(t *testing.T) {
267		priv := stablePrivateKey(t)
268		pub := priv.Public().(ed25519.PublicKey)
269	
270		for _, v := range stableVectors() {
271			t.Run(v.name, func(t *testing.T) {
272				sig := mustB64Decode(t, v.signatureB64)
273				tx := &Transaction{
274					Sender:    append([]byte(nil), pub...),
275					Sequence:  v.sequence,
276					Content:   append([]byte(nil), v.content...),
277					Fee:       v.fee,
278					Expiry:    v.expiry,
279					Signature: append([]byte(nil), sig...),
280				}
281	
282				id := tx.ID()
283	
284				// 钉住摘要结果。
285				if id != v.id {
286					t.Fatalf("id = %s, want %s", id, v.id)
287				}
288				// 小写 64 位十六进制。
289				if len(id) != 64 || id != strings.ToLower(id) {
290					t.Fatalf("id must be 64 lowercase hex chars, got %q", id)
291				}
292				if _, err := hex.DecodeString(id); err != nil {
293					t.Fatalf("id is not valid hex: %v", err)
294				}
295	
296				// 依据公开规则独立重算：摘要对象是含签名的文档，不带签名前缀。
297				wantIDDoc := canonicalTxDoc(v, v.signatureB64)
298				sum := sha256.Sum256([]byte(wantIDDoc))
299				if got := hex.EncodeToString(sum[:]); got != id {
300					t.Fatalf("independent digest %s != %s", got, id)
301				}
302	
303				// 签名字段按字段名排序，位于 sequence 之后；JSON 无空白。
304				if order := jsonKeyOrder(t, []byte(wantIDDoc)); strings.Join(order, ",") !=
305					"content,expiry,fee,sender,sequence,signature" {
306					t.Fatalf("unexpected id doc field order: %v", order)
307				}
308				if strings.ContainsAny(wantIDDoc, " \t\r\n") {
309					t.Fatalf("id doc must contain no whitespace: %s", wantIDDoc)
310				}
311				// 摘要内容明确不含签名前缀。
312				prefixedSum := sha256.Sum256([]byte(stableSigningPrefix + wantIDDoc))
313				if id == hex.EncodeToString(prefixedSum[:]) {
314					t.Fatal("id must hash the JSON document without the signing prefix")
315				}
316	
317				// 重新提供相同字段和签名字节，仍应得到相同标识。
318				tx2 := &Transaction{
319					Sender:    append([]byte(nil), pub...),
320					Sequence:  v.sequence,
321					Content:   append([]byte(nil), v.content...),
322					Fee:       v.fee,
323					Expiry:    v.expiry,
324					Signature: append([]byte(nil), sig...),
325				}
326				if tx2.ID() != id {
327					t.Fatal("re-supplied identical fields and signature must yield the same id")
328				}
329	
330				// 用私钥重新签名应得到同一签名字节（同一公开待签名文本），
331				// 因而标识也保持不变。
332				tx3 := &Transaction{
333					Sender:   append([]byte(nil), pub...),
334					Sequence: v.sequence,
335					Content:  append([]byte(nil), v.content...),
336					Fee:      v.fee,
337					Expiry:   v.expiry,
338				}
339				tx3.Sign(priv)
340				if !bytes.Equal(tx3.Signature, sig) {
341					t.Fatal("re-signing the same bytes must reproduce the pinned signature")
342				}
343				if tx3.ID() != id {
344					t.Fatal("re-signed identical transaction must keep the same id")
345				}
346			})
347		}
348	}
349	
350	// 边界：内容未设置（nil）与零长度字节编码与标识相同；零值与 uint64
351	// 最大值保持完整十进制；二进制内容逐字节保留。
352	func TestEncodingBoundaries(t *testing.T) {
353		priv := stablePrivateKey(t)
354		pub := priv.Public().(ed25519.PublicKey)
355	
356		t.Run("nil-and-empty-content-identical", func(t *testing.T) {
357			mk := func(content []byte) *Transaction {
358				return &Transaction{
359					Sender:    append([]byte(nil), pub...),
360					Sequence:  1,
361					Content:   content,
362					Fee:       0,
363					Expiry:    2,
364					Signature: mustB64Decode(t, stableVectors()[1].signatureB64),
365				}
366			}
367			nilTx := mk(nil)
368			emptyTx := mk([]byte{})
369	
370			if !bytes.Equal(nilTx.SigningBytes(), emptyTx.SigningBytes()) {
371				t.Fatalf("nil and empty content must share signing bytes:\n nil=%q\nempty=%q",
372					nilTx.SigningBytes(), emptyTx.SigningBytes())
373			}
374			if nilTx.ID() != emptyTx.ID() {
375				t.Fatalf("nil and empty content must share id: %s vs %s", nilTx.ID(), emptyTx.ID())
376			}
377			// 与钉住的空内容向量逐字节一致。
378			v := stableVectors()[1]
379			want := []byte(stableSigningPrefix + canonicalTxDoc(v, ""))
380			if !bytes.Equal(nilTx.SigningBytes(), want) {
381				t.Fatalf("empty content encoding drift:\n got %q\nwant %q", nilTx.SigningBytes(), want)
382			}
383			if nilTx.ID() != v.id {
384				t.Fatalf("empty content id = %s, want %s", nilTx.ID(), v.id)
385			}
386		})
387	
388		t.Run("zero-fee-is-plain-zero", func(t *testing.T) {
389			tx := &Transaction{Sender: append([]byte(nil), pub...), Sequence: 1, Fee: 0, Expiry: 2}
390			sb := string(tx.SigningBytes())
391			if !strings.Contains(sb, `"fee":0`) {
392				t.Fatalf("zero fee must be encoded as 0: %q", sb)
393			}
394			if strings.Contains(sb, `"fee":"0"`) || strings.Contains(sb, `"fee":0.0`) {
395				t.Fatalf("fee must be a bare integer: %q", sb)
396			}
397		})
398	
399		t.Run("uint64-max-not-truncated", func(t *testing.T) {
400			const maxUint = ^uint64(0)
401			tx := &Transaction{
402				Sender:   append([]byte(nil), pub...),
403				Sequence: maxUint,
404				Content:  []byte{0xff, 0xff},
405				Fee:      maxUint,
406				Expiry:   maxUint,
407			}
408			sb := tx.SigningBytes()
409			full := "18446744073709551615"
410			for _, field := range []string{`"sequence":`, `"fee":`, `"expiry":`} {
411				if !bytes.Contains(sb, []byte(field+full)) {
412					t.Fatalf("uint64 max for %s must be the full decimal %s: %q", field, full, sb)
413				}
414			}
415			// 数值字段不得带引号、小数点或指数：解码后逐个检查原始 token。
416			var fields map[string]json.RawMessage
417			if err := json.Unmarshal(sb[len(stableSigningPrefix):], &fields); err != nil {
418				t.Fatal(err)
419			}
420			for _, name := range []string{"sequence", "fee", "expiry"} {
421				raw := string(fields[name])
422				if raw != full {
423					t.Fatalf("field %s encoded as %q, want bare %s", name, raw, full)
424				}
425			}
426			// 与钉住向量逐字节一致。
427			v := stableVectors()[3]
428			if want := []byte(stableSigningPrefix + canonicalTxDoc(v, "")); !bytes.Equal(sb, want) {
429				t.Fatalf("uint64 max encoding drift:\n got %q\nwant %q", sb, want)
430			}
431		})
432	
433		t.Run("binary-content-preserved", func(t *testing.T) {
434			raw := []byte{0x00, 0xff, 0xfe, 0x61}
435			tx := &Transaction{
436				Sender:   append([]byte(nil), pub...),
437				Sequence: 5,
438				Content:  raw,
439				Fee:      0,
440				Expiry:   ^uint64(0),
441			}
442			sb := string(tx.SigningBytes())
443			if !strings.Contains(sb, `"content":"AP/+YQ=="`) {
444				t.Fatalf("binary content must be standard padded base64 AP/+YQ==: %q", sb)
445			}
446			// 编码不得尝试把字节当 UTF-8 文本处理。
447			if strings.Contains(sb, string(raw)) {
448				t.Fatalf("raw non-UTF-8 bytes must not appear unencoded: %q", sb)
449			}
450			tx.Sign(priv)
451			if !tx.Verify() {
452				t.Fatal("transaction with binary content must verify")
453			}
454			// 与钉住的二进制内容向量逐字节一致（含标识）。
455			v := stableVectors()[2]
456			if want := stableSigningPrefix + canonicalTxDoc(v, ""); string(tx.SigningBytes()) != want {
457				t.Fatalf("binary content encoding drift:\n got %q\nwant %q", tx.SigningBytes(), want)
458			}
459			if !bytes.Equal(tx.Signature, mustB64Decode(t, v.signatureB64)) {
460				t.Fatal("binary content signature drifted from pinned vector")
461			}
462			if tx.ID() != v.id {
463				t.Fatalf("binary content id = %s, want %s", tx.ID(), v.id)
464			}
465		})
466	}
467	
468	// 公开接口层面：按公开规则准备并签名的交易提交后，返回的标识必须等于
469	// 钉住的摘要；接收行为保持不变。
470	func TestStableEncodingThroughSubmit(t *testing.T) {
471		priv := stablePrivateKey(t)
472		pub := priv.Public().(ed25519.PublicKey)
473	
474		n, err := New(t.TempDir(), Config{
475			Seed:           []byte("stable-encoding-regression"),
476			Validators:     [][]byte{pub},
477			MaxTxsPerBlock: 10,
478		})
479		if err != nil {
480			t.Fatal(err)
481		}
482	
483		v := stableVectors()[0] // sequence 7, fee 3, expiry 99（允许序号缺口入池）
484		tx := &Transaction{
485			Sender:    append([]byte(nil), pub...),
486			Sequence:  v.sequence,
487			Content:   append([]byte(nil), v.content...),
488			Fee:       v.fee,
489			Expiry:    v.expiry,
490			Signature: mustB64Decode(t, v.signatureB64),
491		}
492		if !tx.Verify() {
493			t.Fatal("pinned transaction must verify before submit")
494		}
495		res, err := n.Submit(tx)
496		if err != nil {
497			t.Fatalf("pinned transaction must be accepted: %v", err)
498		}
499		if res.TxID != v.id {
500			t.Fatalf("submit returned id %s, want pinned %s", res.TxID, v.id)
501		}
502		info, err := n.Tx(v.id)
503		if err != nil || info == nil || info.Status != StatusQueued || info.ID != v.id {
504			t.Fatalf("accepted tx must be queryable by the pinned id: %+v (%v)", info, err)
505		}
506	}
507

